def gj(url,params=None,timeout=25):
    if params:
        url += ('&' if '?' in url else '?')+urllib.parse.urlencode(params)
    req=urllib.request.Request(url,headers={'User-Agent':'Mozilla/5.0'})
    with urllib.request.urlopen(req,timeout=timeout) as r:
        return json.loads(r.read().decode('utf-8','replace'))
CAT='https://geo.salvador.ba.gov.br/arcgis/rest/services/Hosted/catalogo_geoservicos/FeatureServer'
CENTER='https://geo.salvador.ba.gov.br/arcgis/rest/services/Hosted/Map/FeatureServer'
PORTAL='https://geo.salvador.ba.gov.br/portal/sharing/rest/content/items/867b93a5cb954dca84dc975aa0d36a6b'
for label,url in [('CATALOGO',CAT),('CENTRO_ANTIGO',CENTER)]:
    try:
        root=gj(url,{'f':'json'})
        print(label+'_ROOT',json.dumps({k:root.get(k) for k in ('serviceDescription','description','capabilities','spatialReference','fullExtent')},ensure_ascii=False,separators=(',',':')))
        print(label+'_LAYERS',json.dumps(root.get('layers') or [],ensure_ascii=False,separators=(',',':')))
        for lyr in (root.get('layers') or [])[:20]:
            lid=lyr.get('id'); meta=gj(url+'/'+str(lid),{'f':'json'})
            fields=[{'name':f.get('name'),'alias':f.get('alias'),'type':f.get('type')} for f in meta.get('fields',[])]
            print(label+'_LAYER_META',lid,json.dumps({'name':meta.get('name'),'geometryType':meta.get('geometryType'),'displayField':meta.get('displayField'),'maxRecordCount':meta.get('maxRecordCount'),'fields':fields},ensure_ascii=False,separators=(',',':')))
            q=gj(url+'/'+str(lid)+'/query',{'f':'json','where':'1=1','outFields':'*','returnGeometry':'false','resultRecordCount':2000})
            feats=q.get('features') or []
            print(label+'_FEATURE_COUNT',lid,len(feats),'EXCEEDED',q.get('exceededTransferLimit'))
            terms=('altim','curva','nivel','nível','cota','topog','mdt','mde','dem','dtm','lidar','laser','relevo','hipso','batim','sicad','cartograf','terreno')
            hits=[]
            for ft in feats:
                attrs=ft.get('attributes') or {}
                text=' | '.join(str(v) for v in attrs.values() if v is not None).lower()
                if any(t in text for t in terms): hits.append(attrs)
            print(label+'_HITS',lid,len(hits))
            for h in hits[:120]: print(label+'_HIT',lid,json.dumps(h,ensure_ascii=False,separators=(',',':')))
    except Exception as e:
        print(label+'_ERR',type(e).__name__,str(e)[:500])
try:
    item=gj(PORTAL,{'f':'json'}); data=gj(PORTAL+'/data',{'f':'json'})
    slim={k:item.get(k) for k in ('id','title','type','owner','url','description','snippet','tags','extent','size','modified')}
    print('ALTIMETRIA_ITEM',json.dumps(slim,ensure_ascii=False,separators=(',',':')))
    print('ALTIMETRIA_DATA',json.dumps(data,ensure_ascii=False,separators=(',',':'))[:12000])
except Exception as e: print('ALTIMETRIA_ITEM_ERR',type(e).__name__,str(e)[:500])
